WHERE o.del_flag = '0' AND o.warehouse_id IN
#{id}
AND o.inbound_no LIKE CONCAT('%', #{bo.inboundNo}, '%')
AND o.company_id = #{bo.companyId}
AND o.warehouse_id = #{bo.warehouseId}
AND o.status = #{bo.status}
AND o.inbound_type = #{bo.inboundType}
AND o.inbound_at >= #{bo.beginInboundAt}
AND o.inbound_at <= #{bo.endInboundAt}
